<script>
document.addEventListener('DOMContentLoaded', () => {
    const modalElement = document.getElementById('programPhotoModal');
    const previewImage = document.getElementById('programPhotoImage');
    const previewTitle = document.getElementById('programPhotoTitle');
    if (!modalElement || !window.bootstrap) return;
    const modal = new bootstrap.Modal(modalElement);
    document.querySelectorAll('.pk-photo-pair a').forEach(link => link.addEventListener('click', event => {
        event.preventDefault();
        const image = link.querySelector('img');
        previewImage.src = link.href;
        previewImage.alt = image?.alt || 'Dokumentasi penerima';
        previewTitle.textContent = link.title || image?.alt || 'Dokumentasi Penerima';
        modal.show();
    }));
    modalElement.addEventListener('hidden.bs.modal', () => { previewImage.src = ''; });
});
</script>
